package com.pavithran.aichat; import android.view.*; import android.widget.*; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import java.util.*; public class ChatAdapter extends RecyclerView.Adapter<ChatAdapter.Holder>{private final List<ChatMessage> items=new ArrayList<>(); public void add(ChatMessage m){items.add(m);notifyItemInserted(items.size()-1);} public void clear(){items.clear();notifyDataSetChanged();} @NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){TextView v=new TextView(p.getContext());v.setTextSize(16);v.setTextColor(p.getResources().getColor(R.color.pavi_text));v.setMaxWidth((int)(p.getResources().getDisplayMetrics().widthPixels*.82));v.setPadding(14,10,14,10);return new Holder(v);} public void onBindViewHolder(@NonNull Holder h,int pos){ChatMessage m=items.get(pos);h.text.setText(m.text());h.text.setBackgroundResource(m.role().equals("user")?R.drawable.bg_message_user:R.drawable.bg_message_ai);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-2,-2);q.setMargins(0,6,0,6);q.gravity=m.role().equals("user")?Gravity.END:Gravity.START;h.text.setLayoutParams(q);} public int getItemCount(){return items.size();} static class Holder extends RecyclerView.ViewHolder{final TextView text;Holder(View v){super(v);text=(TextView)v;}}}
